(() => {
  'use strict';
  const API_URL=String(window.REPORTIA_CONFIG?.API_URL||'').trim();
  const $=id=>document.getElementById(id);
  const MODULES={gastos:{label:'Gastos',icon:'▤'},costos:{label:'Costos',icon:'$'},productividad:{label:'Productividad',icon:'↗'},general:{label:'General',icon:'◎'}};
  const S={session:null,current:'menu',module:null,local:null,cloud:null,cloudMeta:null,history:[],adminRegion:'',adminSnapshot:'',adminSource:'cloud',notificationTimer:null,periodYear:'',periodFrom:'',periodTo:''};
  const norm=s=>String(s??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/\s+/g,' ').trim();
  const upper=s=>norm(s).toUpperCase();
  const money=n=>new Intl.NumberFormat('es-MX',{style:'currency',currency:'MXN',maximumFractionDigits:2}).format(Number(n)||0);
  const num=v=>{if(typeof v==='number')return Number.isFinite(v)?v:0;let s=String(v??'').trim().replace(/\$/g,'').replace(/\s/g,'');if(!s)return 0;if(s.includes(',')&&s.includes('.'))s=s.replace(/,/g,'');else if(s.includes(',')&&!s.includes('.')){const p=s.split(',');s=(p[p.length-1].length===2)?p.join('.'):p.join('');}else s=s.replace(/,/g,'');const n=Number(s);return Number.isFinite(n)?n:0};
  const cleanRegion=s=>upper(s).replace(/^RCV\.?\s*REGION\s*/,'').replace(/^REGION\s*/,'').trim();
  // La REGION operativa se obtiene de Jerarquía Sublibro. El encabezado
  // Des Área Gestión JDE queda como respaldo cuando el sublibro no permite
  // reconocer una región de forma inequívoca.
  const REGION_ALIASES=[
    ['COATZACOALCOS',['COATZACOALCOS','COATZAC','COATZ']],
    ['VILLAHERMOSA',['VILLAHERMOSA','VILLA HERMOSA']],
    ['TUXTLA',['TUXTLA GUTIERREZ','TUXTLA']],
    ['TAPACHULA',['TAPACHULA']],
    ['VERACRUZ',['VERACRUZ']],
    ['OAXACA',['OAXACA']],
    ['MERIDA',['MERIDA']],
    ['CANCUN',['CANCUN']],
    ['CAMPECHE',['CAMPECHE']],
    ['CHETUMAL',['CHETUMAL']]
  ];
  function regionFromSubledger(value,fallback=''){
    const u=upper(value);
    for(const [region,aliases] of REGION_ALIASES){
      if(aliases.some(a=>u.includes(a)))return region;
    }
    // Abreviaturas que sólo se usan cuando aparecen como token independiente.
    if(/(^|[ ._\-])VH([ ._\-]|$)/.test(u) && !/[\-]CO[\-]/.test(u))return 'VILLAHERMOSA';
    if(/(^|[ ._\-])TGZ([ ._\-]|$)/.test(u))return 'TUXTLA';
    return cleanRegion(fallback);
  }
  const esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
  function jsonp(params){return new Promise((resolve,reject)=>{const cb='__rcv34_'+Date.now()+'_'+Math.random().toString(36).slice(2);const sc=document.createElement('script');const q=new URLSearchParams({...params,callback:cb});const timer=setTimeout(()=>{cleanup();reject(new Error('Tiempo de espera agotado.'));},18000);function cleanup(){clearTimeout(timer);try{delete window[cb]}catch(_){}sc.remove()}window[cb]=d=>{cleanup();resolve(d)};sc.onerror=()=>{cleanup();reject(new Error('No fue posible conectar con la nube.'))};sc.src=API_URL+(API_URL.includes('?')?'&':'?')+q;document.head.appendChild(sc)})}
  async function post(params){await fetch(API_URL,{method:'POST',mode:'no-cors',headers:{'Content-Type':'application/x-www-form-urlencoded;charset=UTF-8'},body:new URLSearchParams(params)});return true}
  function build(){if($('rcv34Root'))return;document.body.insertAdjacentHTML('beforeend',`<div id="rcv34Root"><div class="rcv34-shell"><aside class="rcv34-side"><div class="rcv34-brand">REPORT.IA<small>RCV · CONTROL REGIONAL v44</small></div><div class="rcv34-side-user"><strong id="r34User">—</strong><span id="r34Role">—</span></div><div class="rcv34-nav"><button data-r34="menu" class="active">⌂ Menú principal</button><button data-r34="gastos">▤ Gastos</button><button data-r34="costos">$ Costos</button><button data-r34="productividad">↗ Productividad</button><button data-r34="general">◎ General</button><button data-r34="notificaciones">✉ Notificaciones <span id="r34NotifBadge" class="rcv34-notif-badge">0</span></button><button data-r34="sesiones" class="admin-only">◷ Conexiones</button></div><button id="r34Logout" class="rcv34-logout">↪ Cerrar sesión</button></aside><main class="rcv34-main"><div class="rcv34-top"><div><h1 id="r34Title">Centro de control regional</h1><p id="r34Subtitle">Selecciona un módulo para consultar la información.</p></div><span class="rcv34-region" id="r34Region">—</span></div><section id="r34Panel" class="rcv34-panel active"></section></main></div></div><div id="r34Detail" class="rcv34-detail"><div class="rcv34-detail-card"><div class="rcv34-detail-head"><div><h3 id="r34DetailTitle">Detalle</h3><p id="r34DetailSub"></p></div><button class="rcv34-close" id="r34DetailClose">×</button></div><div id="r34DetailBody"></div></div></div>`);
    document.querySelectorAll('[data-r34]').forEach(b=>b.addEventListener('click',()=>navigate(b.dataset.r34)));
    $('r34Logout').addEventListener('click',()=>document.getElementById('logoutBtn')?.click());$('r34DetailClose').onclick=()=>$('r34Detail').classList.remove('open');$('r34Detail').addEventListener('click',e=>{if(e.target===$('r34Detail'))$('r34Detail').classList.remove('open')});
  }
  function sessionRegion(s){if(upper(s.tipo)==='ADMINISTRADOR')return 'TODAS LAS REGIONES';return cleanRegion(s.region||s.tipo||'SIN REGIÓN')}
  function navigate(view){S.current=view;document.querySelectorAll('[data-r34]').forEach(b=>b.classList.toggle('active',b.dataset.r34===view));if(view==='menu')return renderMenu();if(view==='sesiones')return renderSessions();if(view==='notificaciones')return renderNotifications();return renderModule(view)}
  function renderMenu(){S.module=null;$('r34Title').textContent='Centro de control regional';$('r34Subtitle').textContent=upper(S.session.tipo)==='ADMINISTRADOR'?'Carga, valida, publica y supervisa la consulta regional.':'Consulta exclusivamente la información correspondiente a tu región.';const cards=['gastos','costos','productividad','general'].map(k=>`<article class="rcv34-menu-card" data-open="${k}"><div class="ico">${MODULES[k].icon}</div><h3>${MODULES[k].label}</h3><p>${k==='general'?'Vista consolidada de los indicadores más recientes.':'Consulta real, presupuesto, semáforo y detalle por jerarquía.'}</p><div class="status">ABRIR MÓDULO →</div></article>`).join('');$('r34Panel').innerHTML=`<div class="rcv34-menu-grid">${cards}</div>`;document.querySelectorAll('[data-open]').forEach(x=>x.onclick=()=>navigate(x.dataset.open))}
  function status(module,real,budget){if(module==='productividad')return real>=budget?'green':'red';const ar=Math.abs(real),ab=Math.abs(budget);return ar<=ab?'green':'red'}
  function periodLabel(rows){const ps=[...new Set(rows.map(r=>r.period).filter(Boolean))];return ps.length?`${ps[0]}${ps.length>1?' – '+ps[ps.length-1]:''}`:'Periodo del archivo'}
  function totals(rows,module){const real=rows.reduce((a,r)=>a+(Number(r.real)||0),0),budget=rows.reduce((a,r)=>a+(Number(r.budget)||0),0);return{real,budget,diff:module==='productividad'?real-budget:Math.abs(real)-Math.abs(budget),st:status(module,real,budget)}}
  function findHeader(arr,module){let best=-1,score=-1;for(let i=0;i<Math.min(50,arr.length);i++){const rr=(arr[i]||[]).map(upper);const toks=module==='productividad'?['JERARQUIA','REAL','PRESUPUESTO']:['CUENTA','JERARQUIA','PERIODO','REAL','PRESUPUESTO'];const s=toks.reduce((n,t)=>n+(rr.some(x=>x.includes(t))?1:0),0);if(s>score){score=s;best=i}}return best}
  function idx(headers,alts){const hs=headers.map(upper);for(const a of alts){let i=hs.findIndex(x=>x===a);if(i>=0)return i;i=hs.findIndex(x=>x.includes(a));if(i>=0)return i}return-1}
  function inferRegion(arr){for(let i=0;i<Math.min(12,arr.length);i++){const row=arr[i]||[];for(let j=0;j<row.length;j++){if(upper(row[j]).includes('AREA GESTION JDE')||upper(row[j]).includes('ÁREA GESTIÓN JDE')){for(let k=j+1;k<row.length;k++)if(norm(row[k]))return cleanRegion(row[k]);}}}return''}
  const MONTH_LABELS={1:'Ene',2:'Feb',3:'Mar',4:'Abr',5:'May',6:'Jun',7:'Jul',8:'Ago',9:'Sep',10:'Oct',11:'Nov',12:'Dic'};
  function inferYearForColumn(arr,hr,col){
    if(col<0)return'';
    for(let i=hr-1;i>=Math.max(0,hr-5);i--){const v=(arr[i]||[])[col];if(v instanceof Date&&!isNaN(v))return String(v.getFullYear());const n=Number(v);if(Number.isInteger(n)&&n>=2000&&n<=2100)return String(n);const m=String(v??'').match(/\b(20\d{2})\b/);if(m)return m[1]}
    return'';
  }
  function inferFilePeriod(arr,hr){
    for(let i=0;i<Math.min(hr,12);i++)for(const v of (arr[i]||[])){if(v instanceof Date&&!isNaN(v))return MONTH_LABELS[v.getMonth()+1]||''}
    return'';
  }
  function filterPeriod(rows){
    const y=String(S.periodYear||''),from=Number(S.periodFrom||0),to=Number(S.periodTo||0);
    return rows.filter(r=>{if(y&&String(r.year||'')&&String(r.year)!==y)return false;const m=monthOrder(r.period);if(from&&m!==99&&m<from)return false;if(to&&m!==99&&m>to)return false;return true})
  }
  function periodControls(rows){
    const years=[...new Set(rows.map(r=>String(r.year||'')).filter(Boolean))].sort();
    const months=[...new Set(rows.map(r=>monthOrder(r.period)).filter(m=>m>=1&&m<=12))].sort((a,b)=>a-b);
    if(!years.length&&!months.length)return'';
    const yearOpts='<option value="">Todos</option>'+years.map(y=>`<option value="${esc(y)}" ${String(S.periodYear)===y?'selected':''}>${esc(y)}</option>`).join('');
    const monthOpts=(value,allLabel)=>`<option value="">${allLabel}</option>`+months.map(m=>`<option value="${m}" ${String(value)===String(m)?'selected':''}>${MONTH_LABELS[m]}</option>`).join('');
    return `<article class="rcv34-card rcv43-period-card"><div class="rcv43-period-title"><div><b>Filtro del periodo del archivo</b><span>Los KPIs, gráficas, semáforos, unidades y detalle se recalculan con este periodo.</span></div><button id="r43PeriodClear" class="rcv34-btn">Limpiar periodo</button></div><div class="rcv43-period-grid"><label>Año<select id="r43Year">${yearOpts}</select></label><label>Desde<select id="r43From">${monthOpts(S.periodFrom,'Inicio')}</select></label><label>Hasta<select id="r43To">${monthOpts(S.periodTo,'Fin')}</select></label><div class="rcv43-period-hint"><b>${periodRangeLabel()}</b><small>${S.periodFrom&&S.periodTo&&String(S.periodFrom)===String(S.periodTo)?'Comparación contra mes anterior activada':'Puedes seleccionar un solo mes o un rango acumulado'}</small></div></div></article>`;
  }
  function periodRangeLabel(){const f=Number(S.periodFrom||0),t=Number(S.periodTo||0);if(!f&&!t)return S.periodYear?`Año ${S.periodYear} · acumulado completo`:'Todo el periodo disponible';if(f&&t&&f===t)return `${MONTH_LABELS[f]||''}${S.periodYear?' '+S.periodYear:''}`;return `${f?MONTH_LABELS[f]:'Inicio'} – ${t?MONTH_LABELS[t]:'Fin'}${S.periodYear?' · '+S.periodYear:''}`}
  function bindPeriodControls(){
    const y=$('r43Year'),f=$('r43From'),t=$('r43To'),c=$('r43PeriodClear');
    const rerender=()=>{S.periodYear=y?.value||'';S.periodFrom=f?.value||'';S.periodTo=t?.value||'';if(S.periodFrom&&S.periodTo&&Number(S.periodFrom)>Number(S.periodTo)){const z=S.periodFrom;S.periodFrom=S.periodTo;S.periodTo=z}renderCurrentSource()};
    if(y)y.onchange=rerender;if(f)f.onchange=rerender;if(t)t.onchange=rerender;if(c)c.onclick=()=>{S.periodYear='';S.periodFrom='';S.periodTo='';renderCurrentSource()};
  }
  function monthComparison(regionRows,module){
    const m=Number(S.periodFrom||0),to=Number(S.periodTo||0);if(!m||m!==to||m<=1)return'';
    const cur=totals(filterPeriod(regionRows),module),prev=totals(regionRows.filter(r=>monthOrder(r.period)===m-1&&(!S.periodYear||!r.year||String(r.year)===String(S.periodYear))),module);
    if(!prev.real)return'';const change=((Math.abs(cur.real)-Math.abs(prev.real))/Math.abs(prev.real))*100;const better=module==='productividad'?change>=0:change<=0;
    return `<span class="rcv43-month-compare ${better?'better':'worse'}">${change>=0?'▲':'▼'} ${Math.abs(change).toFixed(1)}% vs ${MONTH_LABELS[m-1]}</span>`;
  }
  function redStreak(rs,module){
    const by=monthlyGroups(rs),states=by.map(([name,x])=>({m:monthOrder(name),st:totals(x,module).st})).filter(x=>x.m<99).sort((a,b)=>a.m-b.m);let streak=0,best=0;for(const x of states){if(x.st==='red'){streak++;best=Math.max(best,streak)}else streak=0}return best;
  }
  async function parseFile(file,module){const wb=XLSX.read(await file.arrayBuffer(),{type:'array',raw:true,cellDates:true});let all=[];for(const sn of wb.SheetNames){const arr=XLSX.utils.sheet_to_json(wb.Sheets[sn],{header:1,defval:'',raw:true});if(!arr.length)continue;const hr=findHeader(arr,module);if(hr<0)continue;const h=(arr[hr]||[]).map(norm);const baseRegion=inferRegion(arr);const iRegion=idx(h,['REGION','REGIÓN','AREA GESTION JDE']);const iHier=idx(h,['JERARQUIA CUENTA CONTABLE','JERARQUÍA CUENTA CONTABLE']);const iAccount=idx(h,['DES CUENTA CONTABLE','CUENTA CONTABLE','JERARQUIA CUENTA CONTABLE']);const iSubHierarchy=idx(h,['JERARQUIA SUBLIBRO','JERARQUÍA SUBLIBRO']);const iSub=idx(h,['ULTIMO NIVEL DE SL','ÚLTIMO NIVEL DE SL']);const iBUCode=idx(h,['JERARQUIA UNIDAD DE NEGOCIO JDE','JERARQUÍA UNIDAD DE NEGOCIO JDE']);const iBU=idx(h,['JERARQUIA UNIDAD DE NEGOCIO JDE EN','JERARQUÍA UNIDAD DE NEGOCIO JDE EN','UNIDAD DE NEGOCIO']);const iPeriod=idx(h,['PERIODO','MES']);let iReal=-1,iBudget=-1;const H=h.map(upper);if(module==='productividad'){iReal=H.findIndex(x=>x.includes('REAL GESTION'));iBudget=H.findIndex(x=>x.includes('PRESUPUESTO GESTION'));}else{const realCols=H.map((x,i)=>x.includes('REAL GESTION')?i:-1).filter(i=>i>=0);const budCols=H.map((x,i)=>x.includes('PRESUPUESTO GESTION')?i:-1).filter(i=>i>=0);iReal=realCols.length>1?realCols[realCols.length-1]:realCols[0];iBudget=budCols.length>1?budCols[budCols.length-1]:budCols[0];}
      const dataYear=inferYearForColumn(arr,hr,iReal)||inferYearForColumn(arr,hr,iBudget);const defaultPeriod=inferFilePeriod(arr,hr);
      for(const r of arr.slice(hr+1)){if(!r.some(v=>norm(v)))continue;const subHierarchy=norm(iSubHierarchy>=0?r[iSubHierarchy]:'');const fallbackRegion=cleanRegion(iRegion>=0?r[iRegion]:baseRegion);const region=regionFromSubledger(subHierarchy,fallbackRegion);const hierarchy=norm(iHier>=0?r[iHier]:'SIN JERARQUÍA')||'SIN JERARQUÍA';const account=norm(iAccount>=0?r[iAccount]:hierarchy)||hierarchy;const real=num(iReal>=0?r[iReal]:0),budget=num(iBudget>=0?r[iBudget]:0);if(!region&&real===0&&budget===0)continue;all.push({region:region||'SIN REGIÓN',hierarchy,account,subledger:norm(iSub>=0?r[iSub]:subHierarchy),subledgerHierarchy:subHierarchy,businessUnitCode:norm(iBUCode>=0?r[iBUCode]:''),businessUnit:norm(iBU>=0?r[iBU]:''),period:norm(iPeriod>=0?r[iPeriod]:'')||defaultPeriod,year:dataYear,real,budget,sourceSheet:sn});}}
    if(!all.length)throw new Error('No se encontró una estructura reconocible en el archivo.');
    // Algunos JD exportan PRESUPUESTO 2026 como entero con 4 decimales implícitos
    // (ej. 1157030227 representa 115703.0227). Detectamos esa escala por columna.
    if(module!=='productividad'){
      const ratios=all.filter(r=>Math.abs(r.real)>1&&Math.abs(r.budget)>1).slice(0,500).map(r=>Math.abs(r.budget)/Math.abs(r.real)).sort((a,b)=>a-b);
      const median=ratios.length?ratios[Math.floor(ratios.length/2)]:1;
      if(median>1000)all.forEach(r=>r.budget=r.budget/10000);
    }
    return{module,filename:file.name,uploadedLocalAt:new Date().toISOString(),rows:all,regions:[...new Set(all.map(r=>r.region))],period:periodLabel(all)} }
  function groupRows(rows,key){const m=new Map();rows.forEach(r=>{const k=typeof key==='function'?key(r):(r[key]||'SIN CLASIFICAR');if(!m.has(k))m.set(k,[]);m.get(k).push(r)});return m}
  function unitName(r){return norm(r.businessUnit||r.businessUnitCode||r.subledgerHierarchy||'SIN UNIDAD DE NEGOCIO')||'SIN UNIDAD DE NEGOCIO'}
  function filterRegion(data){if(!data?.rows)return[];if(upper(S.session.tipo)==='ADMINISTRADOR'){const reg=cleanRegion(S.adminRegion||'');return reg?data.rows.filter(r=>cleanRegion(r.region)===reg):data.rows;}const reg=sessionRegion(S.session);return data.rows.filter(r=>cleanRegion(r.region)===reg)}
  function adminRegionLabel(){return upper(S.session.tipo)==='ADMINISTRADOR'?(S.adminRegion||'TODAS LAS REGIONES'):sessionRegion(S.session)}
  function populateRegionFilter(data,source='cloud'){const sel=$(source==='local'?'r34LocalRegionFilter':'r34CloudRegionFilter');if(!sel||upper(S.session.tipo)!=='ADMINISTRADOR')return;const regions=[...new Set((data?.rows||[]).map(r=>cleanRegion(r.region)).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'es'));const keep=S.adminRegion;sel.innerHTML='<option value="">Selecciona una región</option>'+regions.map(r=>`<option value="${esc(r)}">${esc(r)}</option>`).join('');if(keep&&regions.includes(keep))sel.value=keep;else{S.adminRegion='';sel.value='';}sel.onchange=()=>{S.adminRegion=cleanRegion(sel.value);renderCurrentSource()}}
  function publicationCard(meta){return `<div class="rcv34-card rcv34-publication-card"><h3>Publicación oficial en la nube</h3><p>Actualizada: ${esc(meta?.fecha||'—')} · Por: ${esc(meta?.usuario||'—')} ${meta?.snapshotId?'· ID '+esc(meta.snapshotId.slice(0,8)):''}</p></div>`}
  function sema(st){return `<span class="rcv34-semaforo rcv34-${st}"><i class="rcv34-dot"></i>${st==='green'?'VERDE · BIEN':'ROJO · REQUIERE ACCIÓN'}</span>`}
  function pctLabel(rows,module){const t=totals(rows,module),den=Math.abs(t.budget);if(!den)return '—';const p=(Math.abs(t.real)/den)*100;return `${p.toFixed(1)}%`}
  function deviationValue(rows,module){const t=totals(rows,module);return module==='productividad'?Math.max(0,t.budget-t.real):Math.max(0,Math.abs(t.real)-Math.abs(t.budget))}
  function monthOrder(v){const u=upper(v),map={ENE:1,ENERO:1,FEB:2,FEBRERO:2,MAR:3,MARZO:3,ABR:4,ABRIL:4,MAY:5,MAYO:5,JUN:6,JUNIO:6,JUL:7,JULIO:7,AGO:8,AGOSTO:8,SEP:9,SEPT:9,SEPTIEMBRE:9,OCT:10,OCTUBRE:10,NOV:11,NOVIEMBRE:11,DIC:12,DICIEMBRE:12};for(const k in map)if(u===k||u.startsWith(k))return map[k];return 99}
  function monthlyGroups(rows){const g=groupRows(rows,'period');return [...g].filter(([k])=>norm(k)).sort((a,b)=>monthOrder(a[0])-monthOrder(b[0]))}
  function drawTrendChart(c,rows,module){const items=monthlyGroups(rows).map(([name,rs])=>({name,...totals(rs,module)}));const f=fitCanvas(c,260);if(!f||!items.length)return;const{x,w,h}=f,p={l:55,r:20,t:22,b:48},cw=w-p.l-p.r,ch=h-p.t-p.b;const mx=Math.max(...items.flatMap(i=>[Math.abs(i.real),Math.abs(i.budget)]),1);x.font='10px Segoe UI';x.strokeStyle='#e5eaf1';x.fillStyle='#667085';for(let i=0;i<=4;i++){const y=p.t+ch*i/4;x.beginPath();x.moveTo(p.l,y);x.lineTo(w-p.r,y);x.stroke();x.fillText(new Intl.NumberFormat('es-MX',{notation:'compact',maximumFractionDigits:1}).format(mx*(1-i/4)),4,y+3)}const point=(i,v)=>[p.l+(items.length===1?cw/2:cw*i/(items.length-1)),p.t+ch-(Math.abs(v)/mx*ch)];[['real','#273347'],['budget','#9aa6b8']].forEach(([key,color])=>{x.beginPath();x.strokeStyle=color;x.lineWidth=2.5;items.forEach((it,i)=>{const[a,b]=point(i,it[key]);i?x.lineTo(a,b):x.moveTo(a,b)});x.stroke();items.forEach((it,i)=>{const[a,b]=point(i,it[key]);x.fillStyle=color;x.beginPath();x.arc(a,b,3,0,Math.PI*2);x.fill()})});items.forEach((it,i)=>{const[a]=point(i,0);x.fillStyle='#475467';x.textAlign='center';x.fillText(it.name,a,h-15)});x.fillStyle='#273347';x.fillRect(w-170,8,10,10);x.fillStyle='#475467';x.textAlign='left';x.fillText('Real',w-155,17);x.fillStyle='#9aa6b8';x.fillRect(w-105,8,10,10);x.fillStyle='#475467';x.fillText('Presupuesto',w-90,17)}
  function topDeviationBlock(groups,module){const top=[...groups].map(([name,rs])=>({name,rs,dev:deviationValue(rs,module),t:totals(rs,module)})).filter(x=>x.dev>0).sort((a,b)=>b.dev-a.dev).slice(0,5);return `<article class="rcv42-top-card"><div class="rcv42-top-head"><div><h3>Top desviaciones</h3><p>Prioriza las unidades que requieren atención.</p></div><span>${top.length} críticas</span></div><div class="rcv42-top-list">${top.length?top.map((x,i)=>`<button data-top-unit="${esc(x.name)}"><i>${i+1}</i><span><b>${esc(x.name)}</b><small>${module==='productividad'?'Déficit':'Exceso'} ${money(x.dev)}</small></span>${sema('red')}</button>`).join(''):'<div class="rcv34-empty">No hay desviaciones rojas en el filtro actual.</div>'}</div></article>`}
  function regionChooser(data,module,source){const regions=[...new Set((data?.rows||[]).map(r=>cleanRegion(r.region)).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'es'));return `<article class="rcv34-card rcv34-region-step"><div class="rcv34-step-title"><span>1</span><div><h3>Selecciona la región</h3><p>Después se mostrarán únicamente las jerarquías / unidades de negocio que pertenecen a esa región.</p></div></div><div class="rcv34-region-grid">${regions.map(reg=>{const rs=(data.rows||[]).filter(r=>cleanRegion(r.region)===reg),t=totals(rs,module);return `<button class="rcv34-region-card" data-pick-region="${esc(reg)}"><strong>${esc(reg)}</strong><span>${rs.length.toLocaleString()} registros</span><small>Real ${money(t.real)} · Presupuesto ${money(t.budget)}</small>${sema(t.st)}</button>`}).join('')||'<div class="rcv34-empty">No se detectaron regiones en este archivo.</div>'}</div></article>`}
  function renderData(data,module,meta={},source='cloud'){const host=$('r34Data')||$('r34Panel');const admin=upper(S.session.tipo)==='ADMINISTRADOR';if(admin&&!S.adminRegion){host.insertAdjacentHTML('beforeend',regionChooser(data,module,source));host.querySelectorAll('[data-pick-region]').forEach(b=>b.onclick=()=>{S.adminRegion=cleanRegion(b.dataset.pickRegion);const sel=$(source==='local'?'r34LocalRegionFilter':'r34CloudRegionFilter');if(sel)sel.value=S.adminRegion;renderCurrentSource()});return}const regionRows=filterRegion(data);const rows=filterPeriod(regionRows);if(!rows.length){host.insertAdjacentHTML('beforeend',`<div class="rcv34-empty">No hay información disponible para ${admin?(S.adminRegion?'la región '+esc(S.adminRegion):'el filtro seleccionado'):'esta región'}.</div>`);return}const t=totals(rows,module);const groups=groupRows(rows,unitName);const bad=[...groups].filter(([,rs])=>totals(rs,module).st==='red').length;const good=groups.size-bad;const compliance=pctLabel(rows,module);const head=`<div class="rcv34-breadcrumb"><span>Región</span><b>${esc(adminRegionLabel())}</b><i>›</i><strong>Jerarquías / unidades de negocio</strong></div><div class="rcv42-kpis"><article><small>REAL</small><strong>${money(t.real)}</strong><span>${periodRangeLabel()} ${monthComparison(regionRows,module)}</span></article><article><small>PRESUPUESTO</small><strong>${money(t.budget)}</strong><span>Presupuesto acumulado</span></article><article><small>VARIACIÓN</small><strong>${money(t.diff)}</strong><span>${module==='productividad'?'Real - presupuesto':'Exceso absoluto vs presupuesto'}</span></article><article><small>${module==='productividad'?'CUMPLIMIENTO':'USO DE PRESUPUESTO'}</small><strong>${compliance}</strong><span>${bad} rojas · ${good} verdes</span></article><article class="${bad?'alert':''}"><small>INCIDENCIAS ROJAS</small><strong>${bad}</strong><span>de ${groups.size} unidades</span></article></div>`;const chart=`<div class="rcv42-chart-grid"><article class="rcv34-card rcv34-chart-card"><h3>Real vs presupuesto por unidad</h3><p>Principales unidades de ${esc(adminRegionLabel())}.</p><canvas id="r34CompareChart"></canvas></article><article class="rcv34-card rcv34-chart-card"><h3>Evolución mensual</h3><p>Comportamiento del Real contra Presupuesto en el periodo.</p><canvas id="r42TrendChart"></canvas></article><article class="rcv34-card rcv34-chart-card"><h3>Estado de unidades</h3><p>Distribución del semáforo rojo / verde.</p><canvas id="r34StatusChart"></canvas><div class="rcv34-chart-legend"><span><i class="green"></i>${good} verdes</span><span><i class="red"></i>${bad} rojas</span></div></article>${topDeviationBlock(groups,module)}</div>`;const items=[...groups].sort((a,b)=>Math.abs(totals(b[1],module).real)-Math.abs(totals(a[1],module).real)).map(([name,rs])=>{const z=totals(rs,module);const cc=new Set(rs.map(r=>r.hierarchy).filter(Boolean)).size;return `<article class="rcv34-break-item ${z.st==='red'?'is-red':'is-green'}" data-unit="${esc(name)}"><div class="rcv34-break-top"><div><strong>${esc(name)}</strong><small>${cc} jerarquía(s) contable(s) · ${rs.length.toLocaleString()} movimientos</small>${redStreak(groupRows(regionRows,unitName).get(name)||rs,module)>=2?`<em class="rcv43-reincide">↻ ${redStreak(groupRows(regionRows,unitName).get(name)||rs,module)} meses en rojo</em>`:''}</div>${sema(z.st)}</div><div class="amounts"><span>Real<b>${money(z.real)}</b></span><span>Presupuesto<b>${money(z.budget)}</b></span></div></article>`}).join('');const noteBtn=source==='cloud'&&meta?.snapshotId?`<button id="r34RegionNote" class="rcv34-btn">✉ Nueva notificación a ${esc(adminRegionLabel())}</button>`:'';host.insertAdjacentHTML('beforeend',periodControls(regionRows)+executiveReportBar(rows,module,meta,source)+head+chart+`<article class="rcv34-card"><div class="rcv34-card-head"><div><h3>2. Jerarquías que componen la región</h3><p>Selecciona una jerarquía / unidad de negocio para desplegar sus cuentas, semáforo y todos los movimientos que la integran.</p></div>${noteBtn}</div><div class="rcv34-breakdown">${items}</div></article>`);bindPeriodControls();bindExecutiveReport(rows,module,meta,source);drawCharts(groups,module);drawTrendChart($('r42TrendChart'),rows,module);host.querySelectorAll('[data-unit]').forEach(el=>el.onclick=()=>openUnit(data,module,el.dataset.unit,meta,source));host.querySelectorAll('[data-top-unit]').forEach(el=>el.onclick=()=>openUnit(data,module,el.dataset.topUnit,meta,source));if($('r34RegionNote'))$('r34RegionNote').onclick=()=>openRegionNotification(module,meta)}
  function drawCharts(groups,module){requestAnimationFrame(()=>{drawCompareChart($('r34CompareChart'),[...groups].map(([name,rs])=>({name,...totals(rs,module)})).sort((a,b)=>Math.abs(b.real)-Math.abs(a.real)).slice(0,8));drawStatusChart($('r34StatusChart'),[...groups].map(([,rs])=>totals(rs,module).st));})}
  function fitCanvas(c,h=270){if(!c)return null;const dpr=Math.max(1,Math.min(2,window.devicePixelRatio||1)),w=Math.max(300,c.clientWidth||600);c.width=w*dpr;c.height=h*dpr;const x=c.getContext('2d');x.scale(dpr,dpr);return{x,w,h}}
  function drawCompareChart(c,items){const f=fitCanvas(c,285);if(!f)return;const{x,w,h}=f,p={l:52,r:18,t:18,b:75},cw=w-p.l-p.r,ch=h-p.t-p.b;const vals=items.flatMap(i=>[Math.abs(i.real),Math.abs(i.budget)]),mx=Math.max(...vals,1);x.font='10px Segoe UI';x.fillStyle='#667085';x.strokeStyle='#e5eaf1';for(let i=0;i<=4;i++){const y=p.t+ch*i/4;x.beginPath();x.moveTo(p.l,y);x.lineTo(w-p.r,y);x.stroke();const v=mx*(1-i/4);x.fillText(new Intl.NumberFormat('es-MX',{notation:'compact',maximumFractionDigits:1}).format(v),4,y+3)}const slot=cw/Math.max(items.length,1),bw=Math.min(22,slot*.28);items.forEach((it,i)=>{const cx=p.l+slot*i+slot/2,hr=Math.abs(it.real)/mx*ch,hb=Math.abs(it.budget)/mx*ch;x.fillStyle='#273347';x.fillRect(cx-bw-2,p.t+ch-hr,bw,hr);x.fillStyle='#9aa6b8';x.fillRect(cx+2,p.t+ch-hb,bw,hb);x.save();x.translate(cx,h-10);x.rotate(-.55);x.fillStyle='#475467';x.textAlign='right';x.fillText(it.name.slice(0,30),0,0);x.restore()});x.fillStyle='#273347';x.fillRect(w-170,8,10,10);x.fillStyle='#475467';x.fillText('Real',w-155,17);x.fillStyle='#9aa6b8';x.fillRect(w-105,8,10,10);x.fillStyle='#475467';x.fillText('Presupuesto',w-90,17)}
  function drawStatusChart(c,states){const f=fitCanvas(c,220);if(!f)return;const{x,w,h}=f,red=states.filter(s=>s==='red').length,green=states.length-red,total=Math.max(states.length,1),cx=w/2,cy=h/2,r=Math.min(w,h)*.32,th=28;x.lineWidth=th;x.lineCap='butt';let start=-Math.PI/2;[[green,'#16a34a'],[red,'#dc2626']].forEach(([v,color])=>{const a=v/total*Math.PI*2;x.beginPath();x.strokeStyle=color;x.arc(cx,cy,r,start,start+a);x.stroke();start+=a});x.fillStyle='#172033';x.textAlign='center';x.font='700 26px Segoe UI';x.fillText(String(states.length),cx,cy+3);x.font='11px Segoe UI';x.fillStyle='#667085';x.fillText('unidades',cx,cy+22)}
  function threadBlock(module,snapshotId,region,key){if(!snapshotId)return'';const admin=upper(S.session.tipo)==='ADMINISTRADOR';return `<div class="rcv34-thread"><div class="rcv34-thread-head"><div><strong>Seguimiento / notificaciones</strong><p>${admin?'Escribe una nota para los usuarios de esta región. Ellos podrán responderla desde su portal.':'Aquí puedes ver las notas del administrador y responderlas.'}</p></div><div class="rcv42-thread-meta"><span id="r42ThreadStatus" class="rcv42-status pending">PENDIENTE</span><span id="r34ThreadCount" class="rcv34-thread-count">…</span></div></div><div id="r42StatusControls" class="rcv42-status-controls ${admin?'':'rcv34-hidden'}"><button data-r42-status="PENDIENTE">Pendiente</button><button data-r42-status="EN SEGUIMIENTO">En seguimiento</button><button data-r42-status="ATENDIDA">Atendida</button></div><div id="r34ThreadList" class="rcv34-thread-list"><div class="rcv34-thread-empty">Cargando mensajes…</div></div><div class="rcv34-thread-compose"><textarea id="r34NoteText" placeholder="${admin?'Escribe una notificación o comentario…':'Escribe tu respuesta al administrador…'}"></textarea><div><span id="r34NoteMsg" class="rcv34-msg"></span><button id="r34SendNote" class="rcv34-btn primary">${admin?'Enviar notificación':'Responder'}</button></div></div></div>`}
  function openUnit(data,module,unit,meta,source='cloud'){
    const rows=filterPeriod(filterRegion(data)).filter(r=>unitName(r)===unit),t=totals(rows,module),acctGroups=groupRows(rows,'hierarchy');
    $('r34DetailTitle').textContent=unit;$('r34DetailSub').textContent=`${MODULES[module].label} · ${adminRegionLabel()} · ${data.period||''}`;
    const acctCards=[...acctGroups].sort((a,b)=>Math.abs(totals(b[1],module).real)-Math.abs(totals(a[1],module).real)).map(([name,rs])=>{const z=totals(rs,module);return `<article class="rcv34-subhier ${z.st==='red'?'is-red':'is-green'}"><div><strong>${esc(name)}</strong>${sema(z.st)}</div><span>Real <b>${money(z.real)}</b></span><span>Presupuesto <b>${money(z.budget)}</b></span></article>`}).join('');
    const rowState=r=>status(module,r.real,r.budget);
    const makeRows=list=>list.map(r=>`<tr data-detail-state="${rowState(r)}"><td>${esc(r.hierarchy)}</td><td>${esc(r.account)}</td><td>${esc(r.subledgerHierarchy||r.subledger)}</td><td>${esc(r.businessUnitCode)}</td><td>${esc(r.period)}</td><td>${money(r.real)}</td><td>${money(r.budget)}</td><td>${sema(rowState(r))}</td></tr>`).join('');
    const redRows=rows.filter(r=>rowState(r)==='red').length,greenRows=rows.length-redRows;
    let plan='';if(t.st==='red'&&meta?.snapshotId){plan=`<div class="rcv34-plan"><strong>Plan de mejora / acción correctiva</strong><p>Describe qué se hará para corregir la desviación de esta unidad.</p><textarea id="r34PlanText" placeholder="Escribe aquí el plan de mejora..."></textarea><div class="rcv34-plan-actions"><span id="r34PlanMsg" class="rcv34-msg"></span><button id="r34SavePlan" class="rcv34-btn primary">Guardar plan de mejora</button></div></div>`}
    const key=`UNIDAD: ${unit}`,conversation=source==='cloud'&&meta?.snapshotId?threadBlock(module,meta.snapshotId,adminRegionLabel(),key):'';
    $('r34DetailBody').innerHTML=`<div class="rcv34-kpis"><article class="rcv34-kpi"><small>REAL</small><strong>${money(t.real)}</strong></article><article class="rcv34-kpi"><small>PRESUPUESTO</small><strong>${money(t.budget)}</strong></article><article class="rcv34-kpi"><small>VARIACIÓN</small><strong>${money(t.diff)}</strong></article><article class="rcv34-kpi"><small>ESTADO</small><strong>${sema(t.st)}</strong></article></div><article class="rcv34-card"><h3>3. Información de la jerarquía seleccionada</h3><div class="rcv34-subhier-grid">${acctCards}</div></article><article class="rcv34-card"><div class="rcv41-detail-head"><div><h3>4. Detalle completo de la jerarquía</h3><p id="r41DetailCount">${rows.length.toLocaleString()} movimientos mostrados de ${rows.length.toLocaleString()}.</p></div><div class="rcv42-detail-tools"><div class="rcv41-detail-filters" role="group" aria-label="Filtrar movimientos por estado"><button class="rcv41-state-btn active" data-r41-state="all">Todos <b>${rows.length.toLocaleString()}</b></button><button class="rcv41-state-btn red" data-r41-state="red">Rojos <b>${redRows.toLocaleString()}</b></button><button class="rcv41-state-btn green" data-r41-state="green">Verdes <b>${greenRows.toLocaleString()}</b></button></div><input id="r42DetailSearch" class="rcv42-search" placeholder="Buscar cuenta, concepto, sublibro…"></div></div><div class="rcv34-table-wrap"><table class="rcv34-table"><thead><tr><th>Jerarquía contable</th><th>Cuenta / concepto</th><th>Jerarquía Sublibro</th><th>Unidad de negocio JDE</th><th>Periodo</th><th>Real</th><th>Presupuesto</th><th>Estado</th></tr></thead><tbody id="r41DetailRows">${makeRows(rows)}</tbody></table></div><div id="r41DetailEmpty" class="rcv41-detail-empty rcv34-hidden">No hay movimientos con el estado seleccionado.</div></article>${plan}${conversation}`;
    $('r34Detail').classList.add('open');
    let detailState='all';const applyDetailFilter=state=>{detailState=state;const q=upper($('r42DetailSearch')?.value||'');const trs=[...document.querySelectorAll('#r41DetailRows tr')];let shown=0;trs.forEach(tr=>{const stateOk=state==='all'||tr.dataset.detailState===state,textOk=!q||upper(tr.textContent).includes(q),show=stateOk&&textOk;tr.classList.toggle('rcv34-hidden',!show);if(show)shown++});document.querySelectorAll('[data-r41-state]').forEach(btn=>btn.classList.toggle('active',btn.dataset.r41State===state));if($('r41DetailCount'))$('r41DetailCount').textContent=`${shown.toLocaleString()} movimientos mostrados de ${rows.length.toLocaleString()}.`;if($('r41DetailEmpty'))$('r41DetailEmpty').classList.toggle('rcv34-hidden',shown>0)};
    document.querySelectorAll('[data-r41-state]').forEach(btn=>btn.onclick=()=>applyDetailFilter(btn.dataset.r41State));if($('r42DetailSearch'))$('r42DetailSearch').oninput=()=>applyDetailFilter(detailState);
    if($('r34SavePlan'))$('r34SavePlan').onclick=()=>savePlan(module,meta.snapshotId,key);if(conversation){loadThread(module,meta.snapshotId,adminRegionLabel(),key);$('r34SendNote').onclick=()=>sendNote(module,meta.snapshotId,adminRegionLabel(),key)}
  }
  function openRegionNotification(module,meta){const region=adminRegionLabel(),key=`AVISO GENERAL · ${MODULES[module].label}`;$('r34DetailTitle').textContent=`Notificación · ${region}`;$('r34DetailSub').textContent=`${MODULES[module].label} · publicación en nube`;$('r34DetailBody').innerHTML=`<article class="rcv34-card"><h3>Notificación general para la región</h3><p>Este mensaje aparecerá en la bandeja de Notificaciones de los usuarios de ${esc(region)}.</p></article>${threadBlock(module,meta.snapshotId,region,key)}`;$('r34Detail').classList.add('open');loadThread(module,meta.snapshotId,region,key);$('r34SendNote').onclick=()=>sendNote(module,meta.snapshotId,region,key)}
  async function loadThread(module,snapshotId,region,hierarchy){const list=$('r34ThreadList');if(!list)return;try{const d=await jsonp({accion:'v38_thread',token:S.session.token,module,snapshotId,region,hierarchy});if(!d?.ok)throw new Error(d?.mensaje||'No fue posible cargar los mensajes.');const items=d.items||[];$('r34ThreadCount').textContent=items.length+' mensaje'+(items.length===1?'':'s');list.innerHTML=items.length?items.map(x=>`<article class="rcv34-thread-msg ${upper(x.tipo)==='ADMINISTRADOR'?'admin':'user'}"><div><strong>${esc(x.usuario)}</strong><span>${esc(x.fecha)}</span></div><p>${esc(x.texto)}</p><small>${upper(x.tipo)==='ADMINISTRADOR'?'NOTA DEL ADMINISTRADOR':'RESPUESTA DE REGIÓN'}</small></article>`).join(''):'<div class="rcv34-thread-empty">Aún no hay mensajes en este seguimiento.</div>';const unread=items.filter(x=>x.unread).map(x=>x.id);if(unread.length){post({accion:'v38_mark_read',token:S.session.token,ids:unread.join(',')});setTimeout(refreshNotifications,500)}loadThreadStatus(module,snapshotId,region,hierarchy)}catch(e){list.innerHTML=`<div class="rcv34-thread-empty">${esc(e.message)}</div>`}}
  async function loadThreadStatus(module,snapshotId,region,hierarchy){try{const d=await jsonp({accion:'v42_thread_status',token:S.session.token,module,snapshotId,region,hierarchy});if(!d?.ok)return;const st=upper(d.estado||'PENDIENTE'),el=$('r42ThreadStatus');if(el){el.textContent=st;el.className='rcv42-status '+(st==='ATENDIDA'?'done':st==='EN SEGUIMIENTO'?'tracking':'pending')}document.querySelectorAll('[data-r42-status]').forEach(b=>{b.classList.toggle('active',upper(b.dataset.r42Status)===st);b.onclick=()=>setThreadStatus(module,snapshotId,region,hierarchy,b.dataset.r42Status)})}catch(_){}}
  async function setThreadStatus(module,snapshotId,region,hierarchy,estado){if(upper(S.session.tipo)!=='ADMINISTRADOR')return;document.querySelectorAll('[data-r42-status]').forEach(b=>b.disabled=true);try{await post({accion:'v42_set_status',token:S.session.token,module,snapshotId,region,hierarchy,estado});setTimeout(()=>{loadThreadStatus(module,snapshotId,region,hierarchy);renderNotifications()},650)}finally{setTimeout(()=>document.querySelectorAll('[data-r42-status]').forEach(b=>b.disabled=false),800)}}
  async function sendNote(module,snapshotId,region,hierarchy){const txt=$('r34NoteText')?.value.trim(),msg=$('r34NoteMsg'),btn=$('r34SendNote');if(!txt){if(msg){msg.textContent='Escribe un mensaje.';msg.className='rcv34-msg error'}return}if(btn)btn.disabled=true;if(msg){msg.textContent='Enviando…';msg.className='rcv34-msg'}try{await post({accion:'v38_note',token:S.session.token,module,snapshotId,region,hierarchy,texto:txt});if($('r34NoteText'))$('r34NoteText').value='';if(msg){msg.textContent='Notificación enviada.';msg.className='rcv34-msg ok'}setTimeout(()=>{loadThread(module,snapshotId,region,hierarchy);refreshNotifications()},800)}catch(e){if(msg){msg.textContent=e.message;msg.className='rcv34-msg error'}}finally{setTimeout(()=>{if(btn)btn.disabled=false},900)}}
  async function refreshNotifications(){if(!S.session)return;try{const d=await jsonp({accion:'v42_notifications',token:S.session.token});if(!d?.ok)return;const b=$('r34NotifBadge');if(b){b.textContent=String(d.unread||0);b.classList.toggle('has',Number(d.unread)>0)}}catch(_){} }
  async function renderNotifications(){$('r34Title').textContent='Notificaciones';$('r34Subtitle').textContent='Centro de seguimiento de incidencias y respuestas.';$('r34Panel').innerHTML='<div class="rcv34-empty">Consultando mensajes…</div>';try{const d=await jsonp({accion:'v42_notifications',token:S.session.token});if(!d?.ok)throw new Error(d?.mensaje||'No fue posible consultar las notificaciones.');const items=d.items||[];const pending=items.filter(x=>upper(x.estado)!=='ATENDIDA').length,answered=items.filter(x=>upper(x.tipo)!=='ADMINISTRADOR').length;const html=items.length?items.map(x=>`<article class="rcv34-notif-item ${x.unread?'unread':''}" data-notif-module="${esc(x.module)}"><div class="rcv34-notif-icon">${upper(x.tipo)==='ADMINISTRADOR'?'A':'R'}</div><div class="rcv34-notif-main"><div><strong>${esc(x.hierarchy)}</strong><span>${esc(x.fecha)}</span></div><p>${esc(x.texto)}</p><small>${esc(x.usuario)} · ${esc(x.region)} · ${esc(MODULES[x.module]?.label||x.module)}</small></div><span class="rcv42-status ${upper(x.estado)==='ATENDIDA'?'done':upper(x.estado)==='EN SEGUIMIENTO'?'tracking':'pending'}">${esc(x.estado||'PENDIENTE')}</span>${x.unread?'<b class="rcv34-new">NUEVO</b>':''}</article>`).join(''):'<div class="rcv34-empty">No tienes mensajes pendientes.</div>';$('r34Panel').innerHTML=`<div class="rcv42-kpis compact"><article><small>SIN LEER</small><strong>${Number(d.unread||0)}</strong><span>mensajes nuevos</span></article><article><small>ABIERTAS / SEGUIMIENTO</small><strong>${pending}</strong><span>conversaciones activas</span></article><article><small>RESPUESTAS RECIBIDAS</small><strong>${answered}</strong><span>en la bandeja actual</span></article></div><div class="rcv34-section-head"><div><h2>Bandeja de seguimiento</h2><p>Consulta mensajes, respuestas y el estado actual de cada incidencia.</p></div><button id="r34NotifRefresh" class="rcv34-btn">↻ Actualizar</button></div><div class="rcv34-notif-list">${html}</div>`;$('r34NotifRefresh').onclick=renderNotifications;document.querySelectorAll('[data-notif-module]').forEach(el=>el.onclick=()=>navigate(el.dataset.notifModule));const b=$('r34NotifBadge');if(b){b.textContent=String(d.unread||0);b.classList.toggle('has',Number(d.unread)>0)}}catch(e){$('r34Panel').innerHTML=`<div class="rcv34-empty">${esc(e.message)}</div>`}}

  async function savePlan(module,snapshotId,hierarchy){const txt=$('r34PlanText').value.trim(),msg=$('r34PlanMsg');if(!txt){msg.textContent='Escribe el plan de mejora.';msg.className='rcv34-msg error';return}msg.textContent='Guardando…';try{await post({accion:'v34_plan',token:S.session.token,module,snapshotId,region:adminRegionLabel(),hierarchy,texto:txt});msg.textContent='Plan de mejora enviado correctamente.';msg.className='rcv34-msg ok';$('r34SavePlan').disabled=true}catch(e){msg.textContent=e.message;msg.className='rcv34-msg error'}}
  function sourceTabs(){return `<div class="rcv40-source-banner"><div><b>VISTA DEL ADMINISTRADOR · v43</b><span>Elige claramente qué información deseas consultar</span></div></div><div class="rcv34-source-tabs rcv40-source-tabs"><button id="r34TabLocal" class="${S.adminSource==='local'?'active':''}"><span class="rcv40-tab-icon">⚡</span><span><b>PROCESADO EN REAL</b><small>Archivo cargado y procesado en esta sesión · aún no publicado</small></span></button><button id="r34TabCloud" class="${S.adminSource==='cloud'?'active':''}"><span class="rcv40-tab-icon">☁</span><span><b>NUBE PUBLICADA</b><small>Información oficial publicada · histórico de 30 días</small></span></button></div>`}
  function renderCurrentSource(){const admin=upper(S.session.tipo)==='ADMINISTRADOR',box=$('r34Data');if(!box)return;const source=admin?S.adminSource:'cloud';if(source==='local'){populateRegionFilter(S.local,'local');box.innerHTML=S.local?'<div class="rcv34-card rcv40-context-card local"><div><b>⚡ PROCESADO EN REAL</b><span>Estás viendo el archivo procesado en esta sesión. No es todavía la publicación oficial.</span></div></div>':'<div class="rcv34-empty">Procesa un archivo para consultar la vista local.</div>';if(S.local)renderData(S.local,S.module,{},'local')}else{populateRegionFilter(S.cloud,'cloud');box.innerHTML=S.cloud?'<div class="rcv34-card rcv40-context-card cloud"><div><b>☁ NUBE PUBLICADA</b><span>Estás viendo la publicación oficial almacenada en la nube.</span></div></div>'+publicationCard(S.cloudMeta||{}):'<div class="rcv34-empty">Consultando información oficial…</div>';if(S.cloud)renderData(S.cloud,S.module,S.cloudMeta||{},'cloud')}}
  async function renderModule(module){S.module=module;S.local=null;S.cloud=null;S.cloudMeta=null;S.adminRegion='';S.adminSnapshot='';S.periodYear='';S.periodFrom='';S.periodTo='';S.adminSource=upper(S.session.tipo)==='ADMINISTRADOR'?'local':'cloud';$('r34Title').textContent=MODULES[module].label;$('r34Subtitle').textContent=module==='general'?'Consolidado de la publicación más reciente de cada módulo.':'Consulta regional por jerarquía y unidad de negocio.';const admin=upper(S.session.tipo)==='ADMINISTRADOR';if(module==='general')return loadGeneral();$('r34Panel').innerHTML=`<div class="rcv34-section-head"><div><h2>${MODULES[module].label}</h2><p>${admin?'Trabaja en Local para validar y publicar; cambia a Nube para revisar exactamente lo que ya está publicado.':'Consulta la última publicación oficial disponible de tu región.'}</p></div></div>${admin?sourceTabs():''}<div id="r34LocalTools" class="${admin?'':'rcv34-hidden'}"><div class="rcv34-upload"><div class="rcv34-upload-row"><input type="file" id="r34File" accept=".xlsx,.xls"><button id="r34Process" class="rcv34-btn">Procesar archivo</button><button id="r34Publish" class="rcv34-btn primary" disabled>☁ Publicar en nube</button></div><div id="r34UploadMsg" class="rcv34-msg">Carga exclusivamente el archivo de ${MODULES[module].label}.</div></div></div><div id="r34CloudTools" class="${admin?'rcv34-hidden':''}">${admin?`<div class="rcv34-admin-filters"><div><label>Región</label><select id="r34CloudRegionFilter" class="rcv34-history-select"><option value="">Selecciona una región</option></select></div><div><label>Fecha de publicación</label><select id="r34History" class="rcv34-history-select"><option value="">Más reciente</option></select></div><button id="r34Refresh" class="rcv34-btn">↻ Actualizar nube</button></div>`:''}</div>${admin?'<div id="r34LocalRegionTools"><div class="rcv34-admin-filters"><div><label>Región del archivo local</label><select id="r34LocalRegionFilter" class="rcv34-history-select"></select></div></div></div>':''}<div id="r34Data"></div>`;
    if(admin){const setSource=src=>{S.adminSource=src;S.adminRegion='';$('r34TabLocal').classList.toggle('active',src==='local');$('r34TabCloud').classList.toggle('active',src==='cloud');$('r34LocalTools').classList.toggle('rcv34-hidden',src!=='local');$('r34LocalRegionTools').classList.toggle('rcv34-hidden',src!=='local');$('r34CloudTools').classList.toggle('rcv34-hidden',src!=='cloud');if(src==='cloud')loadCloud(module,S.adminSnapshot);else renderCurrentSource()};$('r34TabLocal').onclick=()=>setSource('local');$('r34TabCloud').onclick=()=>setSource('cloud');$('r34Process').onclick=()=>processSelected(module);$('r34Publish').onclick=()=>publishLocal(module);$('r34Refresh').onclick=()=>loadCloud(module,S.adminSnapshot);loadHistory(module);renderCurrentSource()}else loadCloud(module)}
  async function processSelected(module){const file=$('r34File').files?.[0],msg=$('r34UploadMsg');if(!file){msg.textContent='Selecciona un archivo Excel.';msg.className='rcv34-msg error';return}msg.textContent='Procesando y validando…';try{S.local=await parseFile(file,module);S.adminRegion='';populateRegionFilter(S.local,'local');msg.textContent=`Validado: ${S.local.rows.length.toLocaleString()} registros · Región(es): ${S.local.regions.join(', ')}`;msg.className='rcv34-msg ok';$('r34Publish').disabled=false;renderCurrentSource()}catch(e){msg.textContent=e.message;msg.className='rcv34-msg error';$('r34Publish').disabled=true}}
  async function publishLocal(module){if(!S.local)return;const b=$('r34Publish'),msg=$('r34UploadMsg');b.disabled=true;msg.textContent='Publicando…';try{await post({accion:'v34_upload',token:S.session.token,module,payload:JSON.stringify(S.local)});msg.textContent='Publicación enviada correctamente a la nube.';msg.className='rcv34-msg ok';setTimeout(()=>{loadHistory(module);b.disabled=false},1200)}catch(e){msg.textContent=e.message;msg.className='rcv34-msg error';b.disabled=false}}
  async function loadCloud(module,snapshotId=''){const box=$('r34Data');if(!box)return;if(upper(S.session.tipo)==='ADMINISTRADOR'&&S.adminSource!=='cloud')return;box.innerHTML='<div class="rcv34-empty">Consultando información oficial…</div>';try{const d=await jsonp({accion:snapshotId?'v34_snapshot':'v34_module',token:S.session.token,module,snapshotId});if(!d?.ok)throw new Error(d?.mensaje||'No fue posible consultar.');if(!d.disponible){S.cloud=null;box.innerHTML='<div class="rcv34-empty">Aún no hay una publicación disponible para este módulo.</div>';return}S.cloud=d.data;S.cloudMeta=d.meta||{};S.adminSnapshot=snapshotId||'';populateRegionFilter(S.cloud,'cloud');renderCurrentSource()}catch(e){box.innerHTML=`<div class="rcv34-empty">${esc(e.message)}</div>`}}
  async function loadHistory(module){const sel=$('r34History');if(!sel)return;try{const d=await jsonp({accion:'v34_history',token:S.session.token,module});if(!d?.ok)return;S.history=d.items||[];sel.innerHTML='<option value="">Más reciente</option>'+S.history.map(x=>`<option value="${esc(x.snapshotId)}">${esc(x.fecha)} · ${esc(x.usuario)}${(x.regiones||[]).length?' · '+esc((x.regiones||[]).join(', ')):''}</option>`).join('');sel.value=S.adminSnapshot||'';sel.onchange=()=>{S.adminSnapshot=sel.value||'';S.adminRegion='';loadCloud(module,S.adminSnapshot)}}catch(_){}}
  async function loadGeneral(){$('r34Panel').innerHTML='<div class="rcv34-empty">Construyendo centro de control regional…</div>';try{const d=await jsonp({accion:'v34_general',token:S.session.token});if(!d?.ok)throw new Error(d?.mensaje||'No fue posible cargar el consolidado.');const admin=upper(S.session.tipo)==='ADMINISTRADOR';let moduleCards='';const allRegions=new Set();for(const m of ['gastos','costos','productividad']){const x=d.modules?.[m];if(!x?.disponible){moduleCards+=`<article class="rcv34-menu-card"><div class="ico">${MODULES[m].icon}</div><h3>${MODULES[m].label}</h3><p>Sin publicación disponible.</p></article>`;continue}const rows=x.data.rows||[],t=totals(rows,m);rows.forEach(r=>allRegions.add(cleanRegion(r.region)));const redUnits=[...groupRows(rows,unitName)].filter(([,rs])=>totals(rs,m).st==='red').length;moduleCards+=`<article class="rcv34-menu-card" data-general-open="${m}"><div class="ico">${MODULES[m].icon}</div><h3>${MODULES[m].label}</h3><p>Real <b>${money(t.real)}</b><br>Presupuesto <b>${money(t.budget)}</b><br><b>${redUnits}</b> unidades rojas</p><div class="status">${sema(t.st)}</div></article>`}let regional='';if(admin&&allRegions.size){const regs=[...allRegions].filter(Boolean).sort((a,b)=>a.localeCompare(b,'es'));regional=`<article class="rcv34-card rcv42-regional"><div class="rcv42-top-head"><div><h3>Comparativo entre regiones</h3><p>Última publicación disponible de cada módulo. Selecciona una región para revisar su situación.</p></div><span>${regs.length} regiones</span></div><div class="rcv42-region-table"><div class="head"><span>Región</span><span>Gastos</span><span>Costos</span><span>Productividad</span><span>Alertas</span></div>${regs.map(reg=>{let alerts=0;const cells=['gastos','costos','productividad'].map(m=>{const x=d.modules?.[m],rs=(x?.data?.rows||[]).filter(r=>cleanRegion(r.region)===reg);if(!rs.length)return '<span>—</span>';const t=totals(rs,m);if(t.st==='red')alerts++;return `<span>${sema(t.st)}<small>${pctLabel(rs,m)}</small></span>`}).join('');return `<button class="row" data-general-region="${esc(reg)}"><b>${esc(reg)}</b>${cells}<strong class="${alerts?'red':''}">${alerts}</strong></button>`}).join('')}</div></article>`}$('r34Panel').innerHTML=`<div class="rcv34-section-head"><div><h2>Centro de Control Regional</h2><p>Resumen ejecutivo de las publicaciones oficiales más recientes.</p></div><span class="rcv42-update">Actualizado con la última publicación disponible</span></div><div class="rcv34-menu-grid">${moduleCards}</div>${regional}`;document.querySelectorAll('[data-general-open]').forEach(x=>x.onclick=()=>navigate(x.dataset.generalOpen));document.querySelectorAll('[data-general-region]').forEach(x=>x.onclick=()=>{S.adminRegion=cleanRegion(x.dataset.generalRegion);navigate('gastos')})}catch(e){$('r34Panel').innerHTML=`<div class="rcv34-empty">${esc(e.message)}</div>`}}
  async function renderSessions(){if(upper(S.session.tipo)!=='ADMINISTRADOR')return renderMenu();$('r34Title').textContent='Conexiones y actividad';$('r34Subtitle').textContent='Control de accesos y tiempo de consulta de los usuarios.';$('r34Panel').innerHTML='<div class="rcv34-empty">Consultando sesiones…</div>';try{const d=await jsonp({accion:'v34_sessions',token:S.session.token});if(!d?.ok)throw new Error(d?.mensaje||'No fue posible consultar sesiones.');const active=d.items.filter(x=>x.estado==='ACTIVA').length,total=d.items.length,mins=d.items.reduce((a,x)=>a+(Number(x.minutos)||0),0);const trs=d.items.map(x=>`<tr><td>${esc(x.usuario)}</td><td>${esc(x.region)}</td><td>${esc(x.inicio)}</td><td>${esc(x.ultimaActividad)}</td><td>${esc(x.fin||'—')}</td><td>${Number(x.minutos||0).toFixed(1)} min</td><td>${Number(x.consultas||0)}</td><td>${Number(x.planes||0)}</td><td>${esc(x.estado)}</td></tr>`).join('');$('r34Panel').innerHTML=`<div class="rcv34-session-summary"><article class="rcv34-kpi"><small>SESIONES REGISTRADAS</small><strong>${total}</strong></article><article class="rcv34-kpi"><small>ACTIVAS / RECIENTES</small><strong>${active}</strong></article><article class="rcv34-kpi"><small>TIEMPO ACUMULADO</small><strong>${mins.toFixed(0)} min</strong></article></div><article class="rcv34-card"><h3>Bitácora de conexiones</h3><p>Una sesión sin cierre explícito se considera desconectada según su última actividad.</p><div class="rcv34-table-wrap"><table class="rcv34-table"><thead><tr><th>Usuario</th><th>Región</th><th>Inicio</th><th>Última actividad</th><th>Fin</th><th>Duración</th><th>Consultas</th><th>Planes</th><th>Estado</th></tr></thead><tbody>${trs}</tbody></table></div></article>`}catch(e){$('r34Panel').innerHTML=`<div class="rcv34-empty">${esc(e.message)}</div>`}}
  function init(session){build();S.session=session;$('r34User').textContent=session.usuario;$('r34Role').textContent=upper(session.tipo)==='ADMINISTRADOR'?'Administrador del sistema':`Región ${sessionRegion(session)}`;$('r34Region').textContent=sessionRegion(session);renderMenu();refreshNotifications();if(S.notificationTimer)clearInterval(S.notificationTimer);S.notificationTimer=setInterval(refreshNotifications,60000)}
  window.addEventListener('reportia:session',e=>init(e.detail));if(window.REPORTIA_SESSION)init(window.REPORTIA_SESSION);
  function reportFolio(module){const d=new Date(),pad=n=>String(n).padStart(2,'0');const reg=(adminRegionLabel()||'GENERAL').replace(/[^A-Z0-9]/gi,'').slice(0,8).toUpperCase();return `RCV-${upper(module).slice(0,5)}-${reg}-${d.getFullYear()}${pad(d.getMonth()+1)}${pad(d.getDate())}-${pad(d.getHours())}${pad(d.getMinutes())}`}
  function executiveReportBar(rows,module,meta,source){
    return `<article class="rcv44-reportbar"><div><span>REPORTE EJECUTIVO</span><b>Genera una salida lista para reunión o exporta el detalle filtrado.</b><small>Respeta región, año, meses y fuente ${source==='cloud'?'Nube Publicada':'Procesado en Real'}.</small></div><div class="rcv44-report-actions"><button id="r44Report" class="rcv44-report-btn primary">📄 Generar reporte ejecutivo</button><button id="r44Excel" class="rcv44-report-btn">▦ Exportar vista a Excel</button></div></article>`;
  }
  function bindExecutiveReport(rows,module,meta,source){const r=$('r44Report'),x=$('r44Excel');if(r)r.onclick=()=>openReportOptions(rows,module,meta,source);if(x)x.onclick=()=>exportExecutiveExcel(rows,module,meta,source)}
  function openReportOptions(rows,module,meta,source){
    let m=$('r44Options');if(m)m.remove();document.body.insertAdjacentHTML('beforeend',`<div id="r44Options" class="rcv44-modal open"><div class="rcv44-modal-card"><button class="rcv44-x" id="r44Close">×</button><span class="rcv44-kicker">GENERADOR EJECUTIVO</span><h2>Configurar reporte</h2><p>El reporte usará la vista actualmente filtrada: <b>${esc(MODULES[module]?.label||module)}</b> · <b>${esc(adminRegionLabel())}</b> · <b>${esc(periodRangeLabel())}</b>.</p><div class="rcv44-options"><label><input type="checkbox" data-r44="charts" checked> Gráficas y tendencia mensual</label><label><input type="checkbox" data-r44="top" checked> Top desviaciones</label><label><input type="checkbox" data-r44="repeat" checked> Reincidencias</label><label><input type="checkbox" data-r44="detail"> Detalle de movimientos</label><label><input type="checkbox" data-r44="notes" checked> Resumen de seguimiento</label></div><div class="rcv44-modal-actions"><button id="r44Cancel">Cancelar</button><button id="r44Generate" class="primary">Generar reporte</button></div></div></div>`);const close=()=>$('r44Options')?.remove();$('r44Close').onclick=close;$('r44Cancel').onclick=close;$('r44Options').onclick=e=>{if(e.target===$('r44Options'))close()};$('r44Generate').onclick=()=>{const opt={};document.querySelectorAll('[data-r44]').forEach(i=>opt[i.dataset.r44]=i.checked);close();generateExecutiveReport(rows,module,meta,source,opt)}}
  function reportConclusions(rows,module){const groups=[...groupRows(rows,unitName)].map(([name,rs])=>({name,rs,t:totals(rs,module),dev:deviationValue(rs,module),streak:redStreak(rs,module)}));const red=groups.filter(x=>x.t.st==='red').sort((a,b)=>b.dev-a.dev);const out=[];if(red.length)out.push(`${red.length} de ${groups.length} unidades presentan semáforo rojo en el periodo seleccionado.`);else out.push(`No se detectan unidades en rojo en el periodo seleccionado.`);if(red[0])out.push(`${red[0].name} concentra la mayor desviación, por ${money(red[0].dev)}.`);const repeat=groups.filter(x=>x.streak>=2).sort((a,b)=>b.streak-a.streak);if(repeat.length)out.push(`${repeat.length} unidad(es) presentan reincidencia de al menos 2 meses consecutivos en rojo; la mayor racha es de ${repeat[0].streak} meses.`);const by=monthlyGroups(rows);if(by.length>=2){const a=totals(by[by.length-2][1],module),b=totals(by[by.length-1][1],module);if(Math.abs(a.real)>0){const ch=((Math.abs(b.real)-Math.abs(a.real))/Math.abs(a.real))*100;out.push(`El Real del último mes ${ch>=0?'aumentó':'disminuyó'} ${Math.abs(ch).toFixed(1)}% respecto al mes anterior disponible.`)}}return out}
  function reportSvg(rows,module){const data=monthlyGroups(rows).map(([name,rs])=>({name,t:totals(rs,module)}));if(!data.length)return'';const max=Math.max(...data.flatMap(x=>[Math.abs(x.t.real),Math.abs(x.t.budget)]),1),W=760,H=240,p=35,gap=(W-p*2)/Math.max(data.length,1);let bars='';data.forEach((x,i)=>{const bx=p+i*gap+gap*.17,bw=Math.max(8,gap*.25),rh=Math.abs(x.t.real)/max*150,bh=Math.abs(x.t.budget)/max*150;bars+=`<rect x="${bx}" y="${185-rh}" width="${bw}" height="${rh}" rx="3" fill="#344054"/><rect x="${bx+bw+4}" y="${185-bh}" width="${bw}" height="${bh}" rx="3" fill="#98a2b3"/><text x="${bx+bw}" y="210" text-anchor="middle" font-size="10" fill="#667085">${esc(x.name)}</text>`});return `<svg viewBox="0 0 ${W} ${H}" class="r44-svg"><line x1="${p}" y1="185" x2="${W-p}" y2="185" stroke="#d0d5dd"/>${bars}<g font-size="11"><rect x="560" y="12" width="10" height="10" fill="#344054"/><text x="575" y="21">Real</text><rect x="625" y="12" width="10" height="10" fill="#98a2b3"/><text x="640" y="21">Presupuesto</text></g></svg>`}
  function generateExecutiveReport(rows,module,meta,source,opt){const t=totals(rows,module),groups=[...groupRows(rows,unitName)].map(([name,rs])=>({name,rs,t:totals(rs,module),dev:deviationValue(rs,module),streak:redStreak(rs,module)})),reds=groups.filter(x=>x.t.st==='red'),greens=groups.length-reds.length,top=[...reds].sort((a,b)=>b.dev-a.dev).slice(0,5),folio=reportFolio(module),now=new Date().toLocaleString('es-MX'),conclusions=reportConclusions(rows,module);const topHtml=opt.top?`<section><h2>Principales desviaciones</h2><table><thead><tr><th>#</th><th>Unidad</th><th>Real</th><th>Presupuesto</th><th>Desviación</th><th>Estado</th></tr></thead><tbody>${top.map((x,i)=>`<tr><td>${i+1}</td><td>${esc(x.name)}</td><td>${money(x.t.real)}</td><td>${money(x.t.budget)}</td><td>${money(x.dev)}</td><td class="bad">ROJO</td></tr>`).join('')||'<tr><td colspan="6">Sin desviaciones rojas.</td></tr>'}</tbody></table></section>`:'';const repeat=groups.filter(x=>x.streak>=2).sort((a,b)=>b.streak-a.streak);const repeatHtml=opt.repeat?`<section><h2>Reincidencias</h2>${repeat.length?`<div class="chips">${repeat.map(x=>`<span><b>${esc(x.name)}</b> · ${x.streak} meses en rojo</span>`).join('')}</div>`:'<p>No se detectan reincidencias de 2 o más meses consecutivos.</p>'}</section>`:'';const detailHtml=opt.detail?`<section class="page"><h2>Detalle de movimientos</h2><table><thead><tr><th>Jerarquía</th><th>Cuenta / concepto</th><th>Unidad</th><th>Periodo</th><th>Real</th><th>Presupuesto</th><th>Estado</th></tr></thead><tbody>${rows.slice(0,2500).map(r=>{const st=status(module,Number(r.real)||0,Number(r.budget)||0);return `<tr><td>${esc(r.hierarchy)}</td><td>${esc(r.account)}</td><td>${esc(unitName(r))}</td><td>${esc(r.period)}</td><td>${money(r.real)}</td><td>${money(r.budget)}</td><td class="${st==='red'?'bad':'good'}">${st==='red'?'ROJO':'VERDE'}</td></tr>`}).join('')}</tbody></table>${rows.length>2500?'<p><i>Por legibilidad, el PDF limita el detalle a los primeros 2,500 movimientos. Use Exportar a Excel para el universo completo.</i></p>':''}</section>`:'';const html=`<!doctype html><html><head><meta charset="utf-8"><title>${folio}</title><style>@page{size:A4;margin:14mm}*{box-sizing:border-box}body{font-family:Arial,sans-serif;color:#1d2939;margin:0;font-size:11px}.cover{padding:26px;border-radius:16px;background:#f2f4f7;margin-bottom:18px}.brand{font-size:26px;font-weight:900}.brand span{font-size:12px;color:#667085;display:block;margin-top:3px}.cover h1{font-size:25px;margin:35px 0 8px}.meta{display:grid;grid-template-columns:repeat(2,1fr);gap:8px;margin-top:22px}.meta div{background:#fff;border:1px solid #e4e7ec;padding:10px;border-radius:8px}.kpis{display:grid;grid-template-columns:repeat(5,1fr);gap:8px;margin:14px 0}.kpis div{border:1px solid #e4e7ec;border-radius:9px;padding:10px}.kpis small{display:block;color:#667085}.kpis b{display:block;font-size:15px;margin-top:5px}h2{font-size:16px;margin:22px 0 8px;border-bottom:2px solid #344054;padding-bottom:5px}table{border-collapse:collapse;width:100%;font-size:9px}th,td{padding:6px;border-bottom:1px solid #e4e7ec;text-align:left}th{background:#f2f4f7}.bad{color:#b42318;font-weight:bold}.good{color:#067647;font-weight:bold}.r44-svg{width:100%;height:auto;border:1px solid #e4e7ec;border-radius:8px}.conclusions{padding:12px 18px;background:#f9fafb;border-left:4px solid #344054}.conclusions li{margin:7px 0}.chips{display:grid;grid-template-columns:1fr 1fr;gap:7px}.chips span{border:1px solid #fecdca;background:#fef3f2;padding:8px;border-radius:8px}.footer{margin-top:22px;border-top:1px solid #d0d5dd;padding-top:8px;color:#667085;font-size:9px}.page{page-break-before:always}@media print{button{display:none}}</style></head><body><div class="cover"><div class="brand">REPORT.IA<span>Centro de Control Regional</span></div><h1>Reporte Ejecutivo · ${esc(MODULES[module]?.label||module)}</h1><p>Resumen de la información actualmente seleccionada en el portal.</p><div class="meta"><div><small>REGIÓN</small><b>${esc(adminRegionLabel())}</b></div><div><small>PERIODO</small><b>${esc(periodRangeLabel())}</b></div><div><small>FUENTE</small><b>${source==='cloud'?'Nube Publicada':'Procesado en Real'}</b></div><div><small>FOLIO</small><b>${folio}</b></div><div><small>GENERADO POR</small><b>${esc(S.session?.usuario||'—')}</b></div><div><small>FECHA Y HORA</small><b>${now}</b></div></div></div><div class="kpis"><div><small>REAL</small><b>${money(t.real)}</b></div><div><small>PRESUPUESTO</small><b>${money(t.budget)}</b></div><div><small>VARIACIÓN</small><b>${money(t.diff)}</b></div><div><small>ROJAS</small><b>${reds.length}</b></div><div><small>VERDES</small><b>${greens}</b></div></div>${opt.charts?`<section><h2>Evolución mensual · Real vs Presupuesto</h2>${reportSvg(rows,module)}</section>`:''}${topHtml}<section><h2>Conclusiones automáticas</h2><ol class="conclusions">${conclusions.map(x=>`<li>${esc(x)}</li>`).join('')}</ol></section>${repeatHtml}${opt.notes?`<section><h2>Seguimiento ejecutivo</h2><p>Las incidencias y conversaciones se gestionan desde la vista Nube Publicada. Este reporte identifica las unidades que requieren seguimiento con base en el semáforo y reincidencia del periodo.</p></section>`:''}${detailHtml}<div class="footer">${folio} · Generado desde REPORT.IA · ${now}</div><script>window.onload=()=>setTimeout(()=>window.print(),350)<\/script></body></html>`;const w=window.open('','_blank');if(!w){alert('El navegador bloqueó la ventana del reporte. Permite ventanas emergentes para este sitio.');return}w.document.open();w.document.write(html);w.document.close()}
  function exportExecutiveExcel(rows,module,meta,source){if(!window.XLSX){alert('No está disponible el componente de Excel.');return}const t=totals(rows,module),folio=reportFolio(module),summary=[['REPORT.IA · REPORTE EJECUTIVO'],['Folio',folio],['Módulo',MODULES[module]?.label||module],['Región',adminRegionLabel()],['Periodo',periodRangeLabel()],['Fuente',source==='cloud'?'Nube Publicada':'Procesado en Real'],['Generado por',S.session?.usuario||''],['Fecha',new Date().toLocaleString('es-MX')],[],['Real',t.real],['Presupuesto',t.budget],['Variación',t.diff]];const detail=rows.map(r=>({'Región':r.region,'Unidad de negocio':unitName(r),'Jerarquía contable':r.hierarchy,'Cuenta / concepto':r.account,'Jerarquía Sublibro':r.subledgerHierarchy||r.subledger,'Periodo':r.period,'Año':r.year,'Real':r.real,'Presupuesto':r.budget,'Variación':module==='productividad'?(Number(r.real)||0)-(Number(r.budget)||0):Math.abs(Number(r.real)||0)-Math.abs(Number(r.budget)||0),'Estado':status(module,Number(r.real)||0,Number(r.budget)||0)==='red'?'ROJO':'VERDE'}));const wb=XLSX.utils.book_new();XLSX.utils.book_append_sheet(wb,XLSX.utils.aoa_to_sheet(summary),'Resumen');XLSX.utils.book_append_sheet(wb,XLSX.utils.json_to_sheet(detail),'Detalle');XLSX.writeFile(wb,`${folio}.xlsx`)}

})();
